import java.util.*;
import java.math.*;

public class Main {
    static String to_string(String s) {
        return "\"" + s + "\"";
    }

    static String to_string(char[] s) {
        return to_string(new String(s));
    }

    static String to_string(boolean b) {
        return b ? "true" : "false";
    }

    static String to_string(List<Boolean> v) {
        StringBuilder res = new StringBuilder("{");
        boolean first = true;
        for (Boolean b : v) {
            if (!first) res.append(", ");
            first = false;
            res.append(to_string(b));
        }
        res.append("}");
        return res.toString();
    }

    static String to_string(BitSet v, int N) {
        StringBuilder res = new StringBuilder();
        for (int i = 0; i < N; i++) {
            res.append(v.get(i) ? '1' : '0');
        }
        return res.toString();
    }

    static <T> String to_string(List<T> v) {
        StringBuilder res = new StringBuilder("{");
        boolean first = true;
        for (T x : v) {
            if (!first) res.append(", ");
            first = false;
            res.append(to_string(x));
        }
        res.append("}");
        return res.toString();
    }

    static <A, B> String to_string(Pair<A, B> p) {
        return "(" + to_string(p.first) + ", " + to_string(p.second) + ")";
    }

    static <A, B, C> String to_string(Tuple3<A, B, C> p) {
        return "(" + to_string(p.first) + ", " + to_string(p.second) + ", " + to_string(p.third) + ")";
    }

    static <A, B, C, D> String to_string(Tuple4<A, B, C, D> p) {
        return "(" + to_string(p.first) + ", " + to_string(p.second) + ", " + to_string(p.third) + ", " + to_string(p.fourth) + ")";
    }

    static void debug_out(Object... args) {
        // No output needed for debugging
    }

    static <T> T mod_inverse(T a, T m) {
        BigInteger A = (BigInteger) a;
        BigInteger M = (BigInteger) m;
        return (T) A.modInverse(M);
    }

    static class ModularNumber<T extends Modulo> {
        T value;
        public ModularNumber(T val) {
            this.value = val;
        }
        public static <T extends Modulo> ModularNumber<T> normalize(T x) {
            return new ModularNumber<>(x);
        }
        public T get() {
            return value;
        }
        public static <T extends Modulo> T mod() {
            return T.value;
        }
        public ModularNumber<T> add(ModularNumber<T> other) {
            return new ModularNumber<>(value.add(other.value));
        }
        public ModularNumber<T> subtract(ModularNumber<T> other) {
            return new ModularNumber<>(value.subtract(other.value));
        }
        public ModularNumber<T> multiply(ModularNumber<T> other) {
            return new ModularNumber<>(value.multiply(other.value));
        }
        public ModularNumber<T> divide(ModularNumber<T> other) {
            return new ModularNumber<>(value.divide(other.value));
        }
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof ModularNumber)) return false;
            ModularNumber<?> other = (ModularNumber<?>) o;
            return value.equals(other.value);
        }
        public String toString() {
            return value.toString();
        }
    }

    interface Modulo {
        BigInteger getValue();
        static BigInteger value;
    }

    static class Mod3 implements Modulo {
        static BigInteger value;
        public BigInteger getValue() {
            return value;
        }
    }

    static class Pair<A, B> {
        A first;
        B second;
        public Pair(A first, B second) {
            this.first = first;
            this.second = second;
        }
    }

    static class Tuple3<A, B, C> {
        A first;
        B second;
        C third;
        public Tuple3(A first, B second, C third) {
            this.first = first;
            this.second = second;
            this.third = third;
        }
    }

    static class Tuple4<A, B, C, D> {
        A first;
        B second;
        C third;
        D fourth;
        public Tuple4(A first, B second, C third, D fourth) {
            this.first = first;
            this.second = second;
            this.third = third;
            this.fourth = fourth;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        Mod3.value = new BigInteger(sc.next());
        List<ModularNumber<Mod3>> fact = new ArrayList<>();
        List<ModularNumber<Mod3>> inv_fact = new ArrayList<>();
        fact.add(new ModularNumber<>(new Mod3() {{ value = BigInteger.ONE; }}));
        inv_fact.add(new ModularNumber<>(new Mod3() {{ value = BigInteger.ONE; }}));

        // Function to compute combination
        java.util.function.BiFunction<Integer, Integer, ModularNumber<Mod3>> C = (x, y) -> {
            int sz = Math.max(x, y);
            while (fact.size() <= sz) {
                int size = fact.size();
                fact.add(fact.get(fact.size() - 1).multiply(new ModularNumber<>(new Mod3() {{ value = BigInteger.valueOf(size + 1); }})));
                inv_fact.add(new ModularNumber<>(mod_inverse(fact.get(fact.size() - 1).get().getValue(), Mod3.value)));
            }
            if (y < 0 || y > x) return new ModularNumber<>(new Mod3() {{ value = BigInteger.ZERO; }});
            return fact.get(x).multiply(inv_fact.get(y)).multiply(inv_fact.get(x - y));
        };

        List<ModularNumber<Mod3>> ways_arr = new ArrayList<>(Collections.nCopies(m + 1, new ModularNumber<>(new Mod3() {{ value = BigInteger.ZERO; }})));
        List<ModularNumber<Mod3>> ways_count = new ArrayList<>(Collections.nCopies(m + 1, new ModularNumber<>(new Mod3() {{ value = BigInteger.ZERO; }})));
        ways_count.set(0, new ModularNumber<>(new Mod3() {{ value = BigInteger.ONE; }}));

        for (int i = 1; i <= m; i++) {
            for (int j = 0; j < i; j++) {
                int l = j;
                int r = i - 1 - j;
                ModularNumber<Mod3> c = C.apply(l + r, l);
                ModularNumber<Mod3> add = new ModularNumber<>(new Mod3() {{ value = BigInteger.valueOf(l).add(BigInteger.ONE).add(BigInteger.valueOf(r).add(BigInteger.ONE)).divide(BigInteger.TWO)); }});
                ways_arr.set(i, ways_arr.get(i).add(ways_count.get(l).multiply(ways_count.get(r)).multiply(c).multiply(add)));
            }
            for (int j = 0; j < i; j++) {
                int l = j;
                int r = i - 1 - j;
                ModularNumber<Mod3> c = C.apply(l + r, l);
                ModularNumber<Mod3> add = new ModularNumber<>(new Mod3() {{ value = BigInteger.valueOf(l).add(BigInteger.ONE).add(BigInteger.valueOf(r).add(BigInteger.ONE)).divide(BigInteger.TWO); }});
                ModularNumber<Mod3> temp = new ModularNumber<>(new Mod3() {{ value = BigInteger.valueOf(l).add(BigInteger.ONE); }});
                ModularNumber<Mod3> temp2 = new ModularNumber<>(new Mod3() {{ value = BigInteger.valueOf(r).add(BigInteger.ONE); }});
                ModularNumber<Mod3> sum = temp.multiply(new ModularNumber<>(new Mod3() {{ value = BigInteger.ONE; }})).add(temp2.multiply(new ModularNumber<>(new Mod3() {{ value = BigInteger.ONE; }}))).divide(new ModularNumber<>(new Mod3() {{ value = BigInteger.TWO; }}));
                ways_count.set(i, ways_count.get(i).add(ways_count.get(l).multiply(ways_count.get(r)).multiply(c).multiply(sum)));
            }
        }

        ModularNumber<Mod3>[][] dp = new ModularNumber[n + 1][m + 1];
        ModularNumber<Mod3>[][] ways_dp = new ModularNumber[n + 1][m + 1];

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                dp[i][j] = new ModularNumber<>(new Mod3() {{ value = BigInteger.ZERO; }});
                ways_dp[i][j] = new ModularNumber<>(new Mod3() {{ value = BigInteger.ZERO; }});
            }
        }
        ways_dp[0][0] = new ModularNumber<>(new Mod3() {{ value = BigInteger.ONE; }});

        for (int i = 1; i <= n; i++) {
            for (int s = 0; s <= Math.min(m, i); s++) {
                if (s == i) {
                    dp[i][s] = new ModularNumber<>(new Mod3() {{ value = BigInteger.valueOf(s); }});
                    continue;
                }
                for (int d = 1; d <= s + 1; d++) {
                    ModularNumber<Mod3> ft = dp[i - d][s + 1 - d];
                    ModularNumber<Mod3> way = ways_dp[i - d][s + 1 - d];
                    int add = d - 1;
                    ModularNumber<Mod3> c = C.apply(s, add);
                    ModularNumber<Mod3> waysCountAdd = new ModularNumber<>(new Mod3() {{ value = BigInteger.valueOf(add); }});
                    ways_dp[i][s] = ways_dp[i][s].add(way.multiply(waysCountAdd).multiply(c));
                    ModularNumber<Mod3> sumTerm = way.multiply(new ModularNumber<>(new Mod3() {{ value = BigInteger.valueOf(add); } })).add(ft.multiply(waysCountAdd));
                    dp[i][s] = dp[i][s].add(sumTerm.multiply(c));
                }
            }
        }

        System.out.println(dp[n][m]);
    }
}

